{
  "category_edits": [
    {
      "category": "learning_objective",
      "rationale": "Optimize the mean positive-negative softplus margin loss, giving each valid training example equal weight with the existing sampled negative. This may improve HR@10 while preserving the GRU, sampling, and training settings.",
      "edits": [
        {
          "find": "    valid_pos = pos_scores[mask]\n    valid_neg = neg_scores[mask]\n    weights = torch.softmax(valid_neg.detach(), dim=0)\n    pairwise_loss = torch.nn.functional.softplus(valid_neg - valid_pos)\n    return (weights * pairwise_loss).sum()",
          "replace": "    valid_pos = pos_scores[mask]\n    valid_neg = neg_scores[mask]\n    pairwise_loss = torch.nn.functional.softplus(valid_neg - valid_pos)\n    return pairwise_loss.mean()"
        }
      ]
    }
  ],
  "change_summary": "Replace detached negative-score weighting with mean pairwise softplus loss. No architecture or predictor changes are required."
}
